//! Language of content generated by the core (reading notes, annotation block, daily note).
//! The interface has its own translation; this is only what gets written into notes.

use chrono::{Datelike, NaiveDate};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Lang {
    #[default]
    Fr,
    En,
}

impl Lang {
    /// "en" (or "en-US"…) gives English, anything else French.
    pub fn from_code(code: &str) -> Self {
        if code.to_ascii_lowercase().starts_with("en") {
            Lang::En
        } else {
            Lang::Fr
        }
    }

    /// Picks the French or English text.
    pub fn pick<'a>(self, fr: &'a str, en: &'a str) -> &'a str {
        match self {
            Lang::Fr => fr,
            Lang::En => en,
        }
    }

    /// Long date: "samedi 7 novembre 2026" / "Saturday 7 November 2026".
    /// (chrono does not translate day and month names without the `unstable-locales` feature.)
    pub fn long_date(self, d: NaiveDate) -> String {
        const JOURS: [&str; 7] = ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"];
        const MOIS: [&str; 12] =
            ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"];
        const DAYS: [&str; 7] = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
        const MONTHS: [&str; 12] = [
            "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December",
        ];
        let wd = d.weekday().num_days_from_monday() as usize;
        let m = d.month0() as usize;
        match self {
            Lang::Fr => {
                let day = if d.day() == 1 { "1er".to_string() } else { d.day().to_string() };
                format!("{} {} {} {}", JOURS[wd], day, MOIS[m], d.year())
            }
            Lang::En => format!("{} {} {} {}", DAYS[wd], d.day(), MONTHS[m], d.year()),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dates_and_codes() {
        let d = NaiveDate::from_ymd_opt(2026, 11, 7).unwrap();
        assert_eq!(Lang::Fr.long_date(d), "samedi 7 novembre 2026");
        assert_eq!(Lang::En.long_date(d), "Saturday 7 November 2026");
        assert_eq!(Lang::Fr.long_date(NaiveDate::from_ymd_opt(2026, 1, 1).unwrap()), "jeudi 1er janvier 2026");
        assert_eq!(Lang::from_code("en-GB"), Lang::En);
        assert_eq!(Lang::from_code("fr"), Lang::Fr);
        assert_eq!(Lang::from_code(""), Lang::Fr);
    }
}
